const { CONFIGURATION, SETUP_VARIABLES } = require('./constants');

// Read with the setup, never saved by it: the password of the interface is generated by Gladys, or taken from the
// configuration file of Zigbee2mqtt
const READ_VARIABLES = [...SETUP_VARIABLES, CONFIGURATION.Z2M_FRONTEND_AUTH_TOKEN];

/**
 * @description Get current Zigbee2mqtt setup.
 * @returns {Promise} The stored setup variables.
 * @example
 * await this.getSetup();
 */
async function getSetup() {
  const setupMap = {};
  await Promise.all(
    READ_VARIABLES.map(async (key) => {
      const value = await this.gladys.variable.getValue(key, this.serviceId);
      setupMap[key] = value;
    }),
  );
  return setupMap;
}

module.exports = {
  getSetup,
};
